<script setup>
import { ref, computed, onMounted } from 'vue'
import { useAchievementStore } from '@/services/achievementStore'
import { MOCK_ALL_USERS } from '@/services/authStore'

const achievementStore = useAchievementStore()
const isLoading = ref(true)
const stats = ref({ users: { total: 0, students: 0, teachers: 0, admins: 0, active: 0, disabled: 0 }, achievements: { total: 0, pending: 0, approved: 0, rejected: 0, withFiles: 0 }, categories: [], levels: [], sources: [] })

onMounted(() => {
  setTimeout(() => {
    const all = achievementStore.getAll()
    stats.value = {
      users: { total: MOCK_ALL_USERS.length, students: MOCK_ALL_USERS.filter(u => u.role === 'student').length, teachers: MOCK_ALL_USERS.filter(u => u.role === 'teacher').length, admins: MOCK_ALL_USERS.filter(u => u.role === 'admin').length, active: MOCK_ALL_USERS.filter(u => u.status === 'active').length, disabled: MOCK_ALL_USERS.filter(u => u.status === 'disabled').length },
      achievements: { total: all.length, pending: all.filter(a => a.status === 'pending').length, approved: all.filter(a => a.status === 'approved').length, rejected: all.filter(a => a.status === 'rejected').length, withFiles: all.filter(a => a.files && a.files.length > 0).length },
      categories: ['Учебная деятельность', 'Научная деятельность', 'Внеучебная деятельность', 'Дополнительное образование', 'Развитие способностей', 'Личный вклад'].map(c => ({ name: c, count: all.filter(a => a.category === c).length })).filter(c => c.count > 0),
      levels: ['вузовский', 'региональный', 'всероссийский', 'международный'].map(l => ({ name: l, count: all.filter(a => a.level === l).length })).filter(l => l.count > 0),
      sources: ['manual', 'moodle', 'cdo'].map(s => ({ name: { manual: 'Ручной ввод', moodle: 'Moodle', cdo: 'ЦДО' }[s], count: all.filter(a => a.source === s).length })).filter(s => s.count > 0)
    }
    isLoading.value = false
  }, 400)
})

function exportPDF() { const s = stats.value; alert('Экспорт в PDF:\n\nПользователей: ' + s.users.total + '\nСтудентов: ' + s.users.students + '\nДостижений: ' + s.achievements.total + '\nПодтверждено: ' + s.achievements.approved) }
</script>
<template>
  <div class="admin-analytics">
    <div class="page-header"><div><h1>Аналитические отчёты</h1><p class="subtitle">Сводная статистика и экспорт данных системы</p></div><div class="header-actions"><button class="btn btn-primary" @click="exportPDF">Экспорт PDF</button></div></div>
    <div v-if="isLoading" class="loading-state"><div class="spinner"></div><p>Загрузка аналитики...</p></div>
    <template v-else>
      <div class="analytics-section"><h3>Пользователи</h3><div class="analytics-grid"><div class="analytics-card"><span class="ac-value">{{ stats.users.total }}</span><span class="ac-label">Всего</span></div><div class="analytics-card"><span class="ac-value blue">{{ stats.users.students }}</span><span class="ac-label">Студенты</span></div><div class="analytics-card"><span class="ac-value green">{{ stats.users.teachers }}</span><span class="ac-label">Преподаватели</span></div><div class="analytics-card"><span class="ac-value orange">{{ stats.users.admins }}</span><span class="ac-label">Администраторы</span></div><div class="analytics-card"><span class="ac-value green">{{ stats.users.active }}</span><span class="ac-label">Активные</span></div><div class="analytics-card"><span class="ac-value red">{{ stats.users.disabled }}</span><span class="ac-label">Заблокированы</span></div></div></div>
      <div class="analytics-section"><h3>Достижения</h3><div class="analytics-grid"><div class="analytics-card"><span class="ac-value">{{ stats.achievements.total }}</span><span class="ac-label">Всего</span></div><div class="analytics-card"><span class="ac-value orange">{{ stats.achievements.pending }}</span><span class="ac-label">На проверке</span></div><div class="analytics-card"><span class="ac-value green">{{ stats.achievements.approved }}</span><span class="ac-label">Подтверждено</span></div><div class="analytics-card"><span class="ac-value red">{{ stats.achievements.rejected }}</span><span class="ac-label">Отклонено</span></div><div class="analytics-card"><span class="ac-value blue">{{ stats.achievements.withFiles }}</span><span class="ac-label">С файлами</span></div></div></div>
      <div class="analytics-row"><div class="analytics-section flex-1"><h3>По категориям</h3><div class="list-table"><div v-for="cat in stats.categories" :key="cat.name" class="list-row"><span class="list-label">{{ cat.name }}</span><div class="list-bar-bg"><div class="list-bar" :style="{ width: cat.count / stats.achievements.total * 100 + '%' }"></div></div><span class="list-value">{{ cat.count }}</span></div></div></div><div class="analytics-section flex-1"><h3>По уровням</h3><div class="list-table"><div v-for="lvl in stats.levels" :key="lvl.name" class="list-row"><span class="list-label">{{ { вузовский: 'Вуз', региональный: 'Регион', всероссийский: 'РФ', международный: 'Мир' }[lvl.name] || lvl.name }}</span><div class="list-bar-bg"><div class="list-bar blue" :style="{ width: lvl.count / stats.achievements.total * 100 + '%' }"></div></div><span class="list-value">{{ lvl.count }}</span></div></div></div><div class="analytics-section flex-1"><h3>По источникам</h3><div class="list-table"><div v-for="src in stats.sources" :key="src.name" class="list-row"><span class="list-label">{{ src.name }}</span><div class="list-bar-bg"><div class="list-bar orange" :style="{ width: src.count / stats.achievements.total * 100 + '%' }"></div></div><span class="list-value">{{ src.count }}</span></div></div></div></div>
    </template>
  </div>
</template>
