px; background: #e5e7eb; border-radius: 3px; overflow: hidden; }.list-bar { height: 100%; border-radius: 3px; background: #4361ee; transition: width 0.6s ease; }.list-bar.blue { background: #4361ee; }.list-bar.orange { background: #d97706; }.list-value { font-size: 14px; font-weight: 700; color: #1a1a2e; min-width: 30px; text-align: right; }.btn { display: inline-flex; align-items: center; gap: 6px; padding: 9px 18px; border-radius: 10px; font-size: 13px; font-weight: 600; border: none; cursor: pointer; transition: all 0.2s; }.btn-primary { background: #4361ee; color: white; }.btn-primary:hover { background: #3651d4; }</style>